const finding = $input.all().find(i => i.json.finding_key)?.json || {};
const asset = $input.all().find(i => i.json.asset_id)?.json || {};
const control = $input.all().find(i => i.json.control_id && i.json.framework)?.json || {};

const sevBase = {critical:90, high:70, medium:45, low:20};
const critAdd = {critical:10, high:7, medium:4, low:1};
const envAdd = {production:8, staging:3, dev:0};

let score = sevBase[finding.severity] ?? 40;
score += critAdd[asset.criticality] ?? 3;
score += envAdd[asset.environment] ?? 0;
if (finding.occurrence_count >= 3) score += 8;
if (['HIPAA','PCI-DSS','FedRAMP'].includes(finding.framework)) score += 8;
if (['pii','phi','pci'].includes(asset.data_classification)) score += 10;
score = Math.min(100, score);

let priority = 'P4';
if (score >= 85) priority = 'P1';
else if (score >= 70) priority = 'P2';
else if (score >= 50) priority = 'P3';

const controlSla = control.default_sla_hours || {};
let slaHours = controlSla[finding.severity];
if (!slaHours) {
  if (finding.severity === 'critical' && asset.environment === 'production') slaHours = 24;
  else if (finding.severity === 'critical') slaHours = 72;
  else if (finding.severity === 'high' && asset.environment === 'production') slaHours = 168;
  else if (finding.severity === 'high') slaHours = 336;
  else if (finding.severity === 'medium') slaHours = 720;
  else slaHours = 2160;
}
if (finding.occurrence_count >= 3) slaHours = Math.round(slaHours * 0.75);
const slaDue = new Date(Date.now() + slaHours * 3600 * 1000).toISOString();

return [{
  json: {
    findingKey: finding.finding_key, riskScore: score, priority, slaDue,
    repeatedFailure: finding.occurrence_count >= 3
  }
}];

return [{
  json: {
    findingKey: $input.first().json.finding_key,
    riskScore: $input.first().json.risk_score,
    priority: $input.first().json.priority,
    slaDue: $input.first().json.sla_due
  }
}];
